    description:
      '你站在码头边，看着灯塔。灯塔的灯光在闪烁。\n你好像见过闪烁的节奏——三短。三长。三短。SOS。\n灯塔里有人在发信号。但灯塔应该是空的。\n你把目光转向灯塔的底部。有什么引起了你的注意——在灯塔的底部，有一个人影。\n人影在看着你。然后人影消失了。',
    effects: { add_clue: 'clue_area_harbor_lighthouse_signal', san: -2 },
    event_classification: '超自然遭遇',
    normalcy_anchor: false,
    description_variants: {
      visit_2_3: '码头的木板有些不一样了。\n不是变了——是你看它的方式变了。\n上次经过时忽略的细节，这次突然撞进眼里。\n也许是海风的味道比上次浓了一些。\n也许是光线从另一个角度照进来。\n你知道这里是哪里。但你知道——\n你不只是路过。',
      visit_4_6: '你已经在脑子里走了一遍。\n不需要眼睛——某根系缆桩的画面已经刻好了。\n你甚至能预判海风从哪个方向来。\n但你还是走了和上次一样的路。\n每一步都踩在记忆的印子上。\n你知道前方有什么。\n问题是你这次会不会做出同样的选择。',
      visit_7_plus: '你的身体先于你的意识动了。\n不需要思考——码头的木板的每一寸你都记得。\n你知道哪里不平、哪里会响、哪里藏着什么。\n像是你亲手布置的。但你没有。\n你只是来过足够多次，让这个地方长在了你身上。\n长在了你的骨头里。\n现在你是这个地方的一部分了——\n就像它也是你的一部分一样。',
    },
    echo_overlay: '码头比上次来时安静了一些。\n不是人少了——是有什么东西不在了。\n你闻了闻空气。盐味还是一样的。\n但混在里面的另一种味道——消失了。',
