      visit_4_6: '你已经在脑子里走了一遍。\n不需要眼睛——某幅画像的画面已经刻好了。\n你甚至能预判壁炉从哪个方向来。\n但你还是走了和上次一样的路。\n每一步都踩在记忆的印子上。\n你知道前方有什么。\n问题是你这次会不会做出同样的选择。',
      visit_7_plus: '你的身体先于你的意识动了。\n不需要思考——某级台阶的每一寸你都记得。\n你知道哪里不平、哪里会响、哪里藏着什么。\n像是你亲手布置的。但你没有。\n你只是来过足够多次，让这个地方长在了你身上。\n长在了你的骨头里。\n现在你是这个地方的一部分了——\n就像它也是你的一部分一样。',
