      fear_depth: '地面在你脚下变得不真实。你往下看了一眼——不是真的看，是\'感觉\'了一眼。\n下面有东西。很深的东西。\n你听到了一个声音——不是从耳朵进入的，是从骨头里传上来的。\n低频的、持续的振动。像是什么巨大的东西在水底下呼吸。',
